SELECT COUNT(*)
FROM volt_session
WHERE venue_code = #{venueCode}
  AND session_date = #{date}
  AND status = 'open'
  AND booked < capacity
  AND start_time > #{now}

SELECT coach_id, coach_name, title_text, avatar_url, bio, program_no, venue_codes
FROM volt_coach
WHERE coach_id = #{coachId}
